void loadQuickPlans() {
  if (!LittleFS.exists("/quickplans.json")) { loadDefaultQuickPlans(); return; }
  File f = LittleFS.open("/quickplans.json", FILE_READ);
  if (!f || f.size() == 0) { if (f) f.close(); loadDefaultQuickPlans(); return; }
  size_t fSize = f.size();
  std::unique_ptr<char[]> buf(new char[fSize + 1]);
  size_t bytesRead = f.readBytes(buf.get(), fSize);
  buf.get()[bytesRead] = '\0';
  f.close();

  int parsedCount = 0; char* ptr = buf.get();
  while (parsedCount < 4 && (ptr = strstr(ptr, "{\"id\":\"")) != nullptr) {
    QuickPlan &p = activePlans[parsedCount];
    ptr += 7; char* endPtr = strchr(ptr, '\"'); if (!endPtr) break;
    size_t len = endPtr - ptr; if (len >= sizeof(p.id)) len = sizeof(p.id) - 1;
    memcpy(p.id, ptr, len); p.id[len] = '\0'; ptr = endPtr;

    ptr = strstr(ptr, "\"title\":\""); if (!ptr) break; ptr += 9;
    endPtr = strchr(ptr, '\"'); if (!endPtr) break; len = endPtr - ptr;
    if (len >= sizeof(p.title)) len = sizeof(p.title) - 1;
    memcpy(p.title, ptr, len); p.title[len] = '\0'; ptr = endPtr;

    ptr = strstr(ptr, "\"dur\":"); if (!ptr) break; ptr += 6; p.durationSec = (uint32_t)strtoul(ptr, nullptr, 10);
    ptr = strstr(ptr, "\"allowStop\":"); if (!ptr) break; ptr += 12; p.allowStop = (strncmp(ptr, "true", 4) == 0);
    ptr = strstr(ptr, "\"act\":"); if (!ptr) break; ptr += 6; p.active = (strncmp(ptr, "true", 4) == 0);
    if (p.id[0] == '\0' || p.title[0] == '\0' || p.durationSec == 0) { parsedCount = 0; break; }
    parsedCount++;
  }
  if (parsedCount < 4) { loadDefaultQuickPlans(); }
}

void checkForBootRecovery() {
  if (LittleFS.exists("/active_session.json")) {
    File f = LittleFS.open("/active_session.json", FILE_READ);
    if (f) {
      char buf[256]; size_t len = f.readBytes(buf, sizeof(buf) - 1); buf[len] = '\0'; f.close();
      enforceStorageRetention("/sessions.jsonl");
      File sf = LittleFS.open("/sessions.jsonl", FILE_APPEND); if (sf) { sf.println(buf); sf.close(); }
      enforceStorageRetention("/sync_queue.jsonl");
      File qf = LittleFS.open("/sync_queue.jsonl", FILE_APPEND); if (qf) { qf.println(buf); qf.close(); }
    }
    LittleFS.remove("/active_session.json");
  }
}

