void setup() {
  Serial.begin(115200);

  // Pin Initialization
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(RGB_R_PIN, OUTPUT);
  pinMode(RGB_G_PIN, OUTPUT);
  pinMode(RGB_B_PIN, OUTPUT);

  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  // Peripheral Initialization
  Wire.begin(SDA_PIN, SCL_PIN);
  if(display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    display.clearDisplay();
    display.display();
  }

  dht.begin();
  initStorage();

  // Kích hoạt non-blocking WiFi manager từ namespace SmartWiFi
  SmartWiFi::begin();

  coreState = CORE_IDLE;
  buzzer.success();
}

void loop() {
  // 1. Maintain System Services (Non-blocking)
  SmartWiFi::handle(); // Gọi hàm handle từ namespace SmartWiFi
  buzzer.update();
  sysHealth.freeHeap = ESP.getFreeHeap();

  // 2. Hardware Polling
  uint32_t now = millis();
  if (now - lastSensorTs >= INTERVAL_SENSOR) {
    lastSensorTs = now;
    env.temp = dht.readTemperature();
    env.hum = dht.readHumidity();
    env.valid = !(isnan(env.temp) || isnan(env.hum));
  }

  // 3. Sync Background Processing (Mỗi phút)
  if (now % 60000 == 0) {
    processSyncQueue();
  }

  // Minimal delay to feed watchdog
  delay(1);
}
